export const CATEGORIES = [...new Set(GAMES.map((g) => g.category))].sort();
export function getGame(slug) { return GAMES.find((g) => g.slug === slug); }
export function gamesByCategory(slug) { return GAMES.filter((g) => slugify(g.category) === slug); }
export function slugify(text) { return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'game'; }
